void TrajectoryVelocityOptimizer::optimize_trajectory(
  TrajectoryPoints & traj_points, const TrajectoryOptimizerParams & params,
  TrajectoryOptimizerData & data)
{
  if (!params.use_velocity_optimizer) {
    return;
  }

  const auto & current_odometry = data.current_odometry;
  const auto & current_acceleration = data.current_acceleration;
  const auto & current_speed = current_odometry.twist.twist.linear.x;
  const auto & current_linear_acceleration = current_acceleration.accel.accel.linear.x;
  const double & target_pull_out_speed_mps = velocity_params_.target_pull_out_speed_mps;
  const double & target_pull_out_acc_mps2 = velocity_params_.target_pull_out_acc_mps2;

  // Initialize max velocity per point with global max speed
  std::vector<double> max_velocity_per_point(
    traj_points.size(), std::numeric_limits<double>::max());

  const bool max_speed_update_in_place = !velocity_params_.smooth_velocities;

  // Apply lateral acceleration limiting and update max velocity constraints
  if (velocity_params_.limit_lateral_acceleration) {
    // limit_lateral_acceleration returns per-point max velocities based on curvature
    trajectory_velocity_optimizer_utils::limit_lateral_acceleration(
      traj_points, max_velocity_per_point, velocity_params_.max_lateral_accel_mps2,
      velocity_params_.min_limited_speed_mps, data.current_odometry, max_speed_update_in_place);
  }

  auto initial_motion_speed =
    (current_speed > target_pull_out_speed_mps) ? current_speed : target_pull_out_speed_mps;
  auto initial_motion_acc = (current_speed > target_pull_out_speed_mps)
                              ? current_linear_acceleration
                              : target_pull_out_acc_mps2;

  if (velocity_params_.set_engage_speed && (current_speed < target_pull_out_speed_mps)) {
    trajectory_velocity_optimizer_utils::clamp_velocities(
      traj_points, static_cast<float>(initial_motion_speed),
      static_cast<float>(initial_motion_acc));
  }

  // Apply global speed limit to trajectory and max velocity array
  if (velocity_params_.limit_speed) {
    const auto external_velocity_limit = sub_planning_velocity_->take_data();
    const auto max_speed_mps = (external_velocity_limit)
                                 ? static_cast<float>(external_velocity_limit->max_velocity)
                                 : static_cast<float>(velocity_params_.default_max_velocity_mps);
    if (max_speed_update_in_place) {
      // Directly set max velocity on trajectory points
      trajectory_velocity_optimizer_utils::set_max_velocity(traj_points, max_speed_mps);
    } else {
      // Update per-point max velocity constraints
      for (auto & v : max_velocity_per_point) {
        v = std::min(v, static_cast<double>(max_speed_mps));
      }
    }
    if (external_velocity_limit) {
      pub_velocity_limit_->publish(*external_velocity_limit);
    }
  }

  if (velocity_params_.smooth_velocities) {
    if (!continuous_jerk_smoother_) {
      continuous_jerk_smoother_ =
        std::make_shared<ContinuousJerkSmoother>(velocity_params_.continuous_jerk_smoother_params);
    }
    // Pass max velocity per point to enforce lateral acceleration as hard constraint in QP
    trajectory_velocity_optimizer_utils::filter_velocity(
      traj_points, velocity_params_.nearest_dist_threshold_m,
      autoware_utils_math::deg2rad(velocity_params_.nearest_yaw_threshold_deg),
      continuous_jerk_smoother_, current_odometry, max_velocity_per_point);
  }
}

void limit_lateral_acceleration(
  TrajectoryPoints & input_trajectory_array, std::vector<double> & max_velocity_per_point,
  const double max_lateral_accel_mps2, const double min_limited_speed_mps,
  const Odometry & current_odometry, const bool inplace)
{
  if (input_trajectory_array.empty()) {
    return;
  }

  const size_t traj_size = input_trajectory_array.size();

  auto get_delta_time = [](const auto & next, const auto & current) -> double {
    return next->time_from_start.sec + next->time_from_start.nanosec * 1e-9 -
           (current->time_from_start.sec + current->time_from_start.nanosec * 1e-9);
  };

  const auto & current_position = current_odometry.pose.pose.position;
  const auto start_index = motion_utils::findNearestIndex(input_trajectory_array, current_position);
  const size_t end_index = traj_size - 1;

  // Ensure we have a valid range
  if (start_index >= traj_size || start_index > end_index) {
    return;
  }

  const auto start_itr = std::next(
    input_trajectory_array.begin(),
    static_cast<std::vector<TrajectoryPoint>::difference_type>(start_index));

  size_t current_index = start_index;
  for (auto itr = start_itr; itr < std::prev(input_trajectory_array.end());
       ++itr, ++current_index) {
    const double current_speed = std::abs(itr->longitudinal_velocity_mps);
    if (current_speed < min_limited_speed_mps) {
      // No modification needed for low speeds
      continue;
    }

    const auto current_pose = itr->pose;
    const auto next_pose = std::next(itr)->pose;
    const auto delta_time = get_delta_time(std::next(itr), itr);
    constexpr double epsilon_dt = 1.0e-3;
    if (delta_time <= epsilon_dt) {
      continue;
    }

    tf2::Quaternion q_current;
    tf2::Quaternion q_next;

    const double yaw_current = autoware_utils_geometry::get_rpy(current_pose).z;
    const double yaw_next = autoware_utils_geometry::get_rpy(next_pose).z;
    const double delta_yaw = autoware_utils_geometry::normalize_radian(yaw_next - yaw_current);
    constexpr double epsilon_yaw_rate = 1.0e-5;
    const double yaw_rate = std::max(std::abs(delta_yaw / delta_time), epsilon_yaw_rate);
    const double lateral_acceleration = current_speed * yaw_rate;

    if (lateral_acceleration < max_lateral_accel_mps2) {
      // No modification needed
      continue;
    }

    // Compute velocity limit based on lateral acceleration constraint
    const double limited_velocity =
      std::max(max_lateral_accel_mps2 / yaw_rate, min_limited_speed_mps);

    // Update max velocity constraint for this point
    max_velocity_per_point.at(current_index) =
      std::min(max_velocity_per_point.at(current_index), limited_velocity);

    // Inplace trajectory update
    if (inplace) {
      itr->longitudinal_velocity_mps = static_cast<float>(max_velocity_per_point.at(current_index));
    }
  }
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

auto get_delta_time = [](const auto & next, const auto & current) -> double {
  return next->time_from_start.sec + next->time_from_start.nanosec * 1e-9 -
         (current->time_from_start.sec + current->time_from_start.nanosec * 1e-9);
};

geometry_msgs::msg::Vector3 get_rpy(const geometry_msgs::msg::Pose & pose)
{
  return get_rpy(pose.orientation);
}

geometry_msgs::msg::Vector3 get_rpy(const geometry_msgs::msg::Quaternion & quat)
{
  geometry_msgs::msg::Vector3 rpy;
  tf2::Quaternion q(quat.x, quat.y, quat.z, quat.w);
  tf2::Matrix3x3(q).getRPY(rpy.x, rpy.y, rpy.z);
  return rpy;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

void clamp_velocities(
  TrajectoryPoints & input_trajectory_array, const float min_velocity, const float min_acceleration)
{
  std::for_each(
    input_trajectory_array.begin(), input_trajectory_array.end(),
    [min_velocity, min_acceleration](TrajectoryPoint & point) {
      point.longitudinal_velocity_mps = std::max(point.longitudinal_velocity_mps, min_velocity);
      point.acceleration_mps2 = std::max(point.acceleration_mps2, min_acceleration);
    });
}

void set_max_velocity(TrajectoryPoints & input_trajectory_array, const float max_velocity)
{
  if (input_trajectory_array.empty()) {
    return;
  }

  // Handle single-point trajectory
  if (input_trajectory_array.size() == 1) {
    input_trajectory_array[0].longitudinal_velocity_mps =
      std::min(input_trajectory_array[0].longitudinal_velocity_mps, max_velocity);
    input_trajectory_array[0].acceleration_mps2 = 0.0f;
    return;
  }

  std::vector<std::pair<size_t, size_t>> modified_segment_indices;
  std::vector<double> original_dts;
  original_dts.reserve(input_trajectory_array.size() - 1);

  // Lambda to compute dt from velocity change and acceleration
  auto compute_dt_using_velocity_and_acc =
    [](const TrajectoryPoint & from, const TrajectoryPoint & to) -> double {
    const auto dv = static_cast<double>(to.longitudinal_velocity_mps) -
                    static_cast<double>(from.longitudinal_velocity_mps);
    const auto acc = static_cast<double>(from.acceleration_mps2);
    constexpr double epsilon_acceleration = 1e-6;
    const auto denominator_acc = std::max(std::abs(acc), epsilon_acceleration);
    return std::abs(dv) / denominator_acc;
  };

  // Store original dt values computed from velocity and acceleration
  for (size_t i = 0; i < input_trajectory_array.size() - 1; ++i) {
    original_dts.push_back(
      compute_dt_using_velocity_and_acc(input_trajectory_array[i], input_trajectory_array[i + 1]));
  }

  // Identify segments where velocity exceeds max_velocity
  size_t segment_start = 0;
  bool in_segment = false;

  for (size_t i = 0; i < input_trajectory_array.size(); ++i) {
    const bool exceeds_max = input_trajectory_array[i].longitudinal_velocity_mps > max_velocity;

    if (exceeds_max && !in_segment) {
      // Start of new segment
      segment_start = i;
      in_segment = true;
    } else if (!exceeds_max && in_segment) {
      // End of segment
      modified_segment_indices.emplace_back(segment_start, i - 1);
      in_segment = false;
    }
  }

  // Handle case where segment extends to end of trajectory
  if (in_segment) {
    modified_segment_indices.emplace_back(segment_start, input_trajectory_array.size() - 1);
  }

  // Cap velocities and set accelerations in offending segments
  for (const auto & [start, end] : modified_segment_indices) {
    // Cap velocities for all points in segment
    for (size_t i = start; i <= end; ++i) {
      input_trajectory_array[i].longitudinal_velocity_mps = max_velocity;
    }

    // Set acceleration to 0 for all intermediate points (constant velocity)
    // Points from start to end-1 have no velocity change to next point
    for (size_t i = start; i < end; ++i) {
      input_trajectory_array[i].acceleration_mps2 = 0.0f;
    }
  }

  // Recalculate accelerations at segment boundaries (transitions)
  for (const auto & [start, end] : modified_segment_indices) {
    // Update acceleration for point right before segment start (transition INTO segment)
    // Skip if segment starts at index 0 (no point before it)
    if (start > 0) {
      const size_t idx_before = start - 1;
      const double dt = original_dts[idx_before];
      const auto v_before =
        static_cast<double>(input_trajectory_array[idx_before].longitudinal_velocity_mps);
      const auto v_start =
        static_cast<double>(input_trajectory_array[start].longitudinal_velocity_mps);
      const double new_acc = (v_start - v_before) / dt;
      input_trajectory_array[idx_before].acceleration_mps2 = static_cast<float>(new_acc);
    }

    // Update acceleration for last point of segment (transition OUT OF segment)
    // Skip if segment ends at last trajectory point (should remain 0.0)
    if (end < input_trajectory_array.size() - 1) {
      const double dt = original_dts[end];
      const auto v_end = static_cast<double>(input_trajectory_array[end].longitudinal_velocity_mps);
      const auto v_after =
        static_cast<double>(input_trajectory_array[end + 1].longitudinal_velocity_mps);
      const double new_acc = (v_after - v_end) / dt;
      input_trajectory_array[end].acceleration_mps2 = static_cast<float>(new_acc);
    }
  }

  // Ensure last point always has zero acceleration
  input_trajectory_array.back().acceleration_mps2 = 0.0f;
}

void filter_velocity(
  TrajectoryPoints & input_trajectory, const double nearest_dist_threshold_m,
  const double nearest_yaw_threshold_rad, const std::shared_ptr<ContinuousJerkSmoother> & smoother,
  const Odometry & current_odometry, const std::vector<double> & max_velocity_per_point)
{
  if (!smoother) {
    auto clock = rclcpp::Clock::make_shared(RCL_ROS_TIME);
    RCLCPP_ERROR_THROTTLE(
      rclcpp::get_logger("trajectory_velocity_optimizer"), *clock, 5000,
      "ContinuousJerkSmoother is not initialized");
    return;
  }

  if (input_trajectory.size() < 2) {
    return;
  }

  const size_t traj_closest = autoware::motion_utils::findFirstNearestIndexWithSoftConstraints(
    input_trajectory, current_odometry.pose.pose, nearest_dist_threshold_m,
    nearest_yaw_threshold_rad);

  // Clip trajectory from closest point
  TrajectoryPoints clipped;
  clipped.insert(
    clipped.end(),
    input_trajectory.begin() + static_cast<TrajectoryPoints::difference_type>(traj_closest),
    input_trajectory.end());
  input_trajectory = clipped;

  // Also clip the max velocity array if provided
  std::vector<double> clipped_max_vel;
  if (!max_velocity_per_point.empty() && max_velocity_per_point.size() > traj_closest) {
    clipped_max_vel.insert(
      clipped_max_vel.end(),
      max_velocity_per_point.begin() +
        static_cast<std::vector<double>::difference_type>(traj_closest),
      max_velocity_per_point.end());
  }

  // Apply continuous jerk smoother with per-point velocity constraints
  if (!smoother->apply(input_trajectory, input_trajectory, clipped_max_vel)) {
    auto clock = rclcpp::Clock::make_shared(RCL_ROS_TIME);
    RCLCPP_WARN_THROTTLE(
      rclcpp::get_logger("trajectory_velocity_optimizer"), *clock, 5000,
      "Continuous jerk smoother optimization failed.");
  }
}

size_t findFirstNearestIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  validateNonEmpty(points);

  {  // with dist and yaw thresholds
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (squared_dist_threshold < squared_dist || yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with dist threshold
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);

      if (squared_dist_threshold < squared_dist) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with yaw threshold
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  // without any threshold
  return findNearestIndex(points, pose.position);
}

void validateNonEmpty(const T & points)
{
  if (points.empty()) {
    autoware_utils_system::print_backtrace();
    throw std::invalid_argument("[autoware_motion_utils] validateNonEmpty(): Points is empty.");
  }
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
  const geometry_msgs::msg::Pose & base_pose, const geometry_msgs::msg::Pose & target_pose)
{
  const auto base_yaw = tf2::getYaw(base_pose.orientation);
  const auto target_yaw = tf2::getYaw(target_pose.orientation);
  return autoware_utils_math::normalize_radian(target_yaw - base_yaw);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool ContinuousJerkSmoother::apply(
  const TrajectoryPoints & input, TrajectoryPoints & output,
  const std::vector<double> & max_velocity_per_point)
{
  output = input;

  if (input.empty()) {
    RCLCPP_WARN(logger_, "Input TrajectoryPoints to the continuous jerk smoother is empty.");
    return false;
  }

  if (input.size() == 1) {
    // No need to do optimization
    return true;
  }

  const double a_max = params_.max_accel;
  const double a_min = params_.min_decel;
  const double j_max = params_.max_jerk;
  const double j_min = params_.min_jerk;
  const double over_j_weight = params_.over_j_weight;
  const double over_v_weight = params_.over_v_weight;
  const double over_a_weight = params_.over_a_weight;
  // const double a_stop_decel = 0.0;
  const double smooth_weight = params_.jerk_weight;
  const double velocity_tracking_weight = params_.velocity_tracking_weight;
  const double accel_tracking_weight = params_.accel_tracking_weight;

  // Search for stop point (zero velocity) starting from index 1
  // to avoid getting 0 as a stop point at the beginning
  const auto zero_vel_id = autoware::motion_utils::searchZeroVelocityIndex(input, 1, input.size());

  // Determine optimization horizon N
  const size_t total_size = input.size();
  size_t N = total_size;
  if (zero_vel_id) {
    N = *zero_vel_id + 1;  // Optimize only up to stop point
  }

  if (N < 2) {
    RCLCPP_WARN(logger_, "Trajectory too small for optimization (N=%zu)", N);
    return false;
  }

  // Store reference velocities from input trajectory (for tracking objective)
  std::vector<double> v_ref_arr(N, 0.0);
  for (size_t i = 0; i < N; ++i) {
    v_ref_arr.at(i) = input.at(i).longitudinal_velocity_mps;
  }

  output = input;

  const std::vector<double> interval_dist_arr = calc_trajectory_interval_distance(input);

  // v_max_arr: Per-point velocity upper bounds (e.g., from lateral acceleration limits)
  std::vector<double> v_max_arr(N, 0.0);
  if (max_velocity_per_point.empty()) {
    // Fallback: use a large value if max_velocity_per_point is not provided
    // (should not happen in practice as it's always initialized in trajectory_velocity_optimizer)
    std::fill(v_max_arr.begin(), v_max_arr.end(), 1000.0);
  } else {
    for (size_t i = 0; i < N; ++i) {
      v_max_arr.at(i) = max_velocity_per_point.at(i);
    }
  }

  /*
   * QP Formulation:
   * x = [
   *      b[0], b[1], ..., b[N-1],               : 0 ~ N-1
   *      a[0], a[1], .... a[N-1],               : N ~ 2N-1
   *      delta[0], ..., delta[N-1],             : 2N ~ 3N-1
   *      sigma[0], sigma[1], ...., sigma[N-1],  : 3N ~ 4N-1
   *      gamma[0], gamma[1], ..., gamma[N-1]    : 4N ~ 5N-2
   *     ]
   *
   * b[i]  : velocity^2
   * delta : 0 < b[i]-delta[i] < max_velocity^2 (velocity upper bound)
   * sigma : a_min < a[i] - sigma[i] < a_max
   * gamma : jerk_min < pseudo_jerk[i] * ref_vel[i] - gamma[i] < jerk_max
   */
  const uint32_t IDX_B0 = 0;
  const uint32_t IDX_A0 = N;
  const uint32_t IDX_DELTA0 = 2 * N;
  const uint32_t IDX_SIGMA0 = 3 * N;
  const uint32_t IDX_GAMMA0 = 4 * N;

  const uint32_t l_variables = 5 * N;  // gamma has N-1 elements
  // If zero velocity is found, add 1 constraint for end constraints
  const uint32_t l_constraints =
    4 * N - 2 + (zero_vel_id ? 1 : 0);  // N + N + (N-1) + (N-1) = 4N - 2

  // Allocate matrices
  Eigen::MatrixXd A = Eigen::MatrixXd::Zero(l_constraints, l_variables);
  std::vector<double> lower_bound(l_constraints, 0.0);
  std::vector<double> upper_bound(l_constraints, 0.0);
  Eigen::MatrixXd P = Eigen::MatrixXd::Zero(l_variables, l_variables);
  std::vector<double> q(l_variables, 0.0);

  /**************************************************************/
  /**************** design objective function *******************/
  /**************************************************************/

  // Jerk minimization: d(ai)/ds * v_ref -> minimize weight * ((a1 - a0) / ds * v_ref)^2 * ds
  for (size_t i = 0; i < N - 1; ++i) {
    const double ref_vel = 0.5 * (v_ref_arr.at(i) + v_ref_arr.at(i + 1));
    const double interval_dist = std::max(interval_dist_arr.at(i), 0.0001);
    const double w_x_ds_inv = (1.0 / interval_dist) * std::max(ref_vel, 0.1);
    P(IDX_A0 + i, IDX_A0 + i) += smooth_weight * w_x_ds_inv * w_x_ds_inv * interval_dist;
    P(IDX_A0 + i, IDX_A0 + i + 1) -= smooth_weight * w_x_ds_inv * w_x_ds_inv * interval_dist;
    P(IDX_A0 + i + 1, IDX_A0 + i) -= smooth_weight * w_x_ds_inv * w_x_ds_inv * interval_dist;
    P(IDX_A0 + i + 1, IDX_A0 + i + 1) += smooth_weight * w_x_ds_inv * w_x_ds_inv * interval_dist;
  }

  // Reference velocity tracking: minimize weight * (b - v_ref^2)^2
  // Expands to: weight * b^2 - 2*weight*v_ref^2*b + const
  // P term: weight on b^2
  // q term: -2*weight*v_ref^2 on b
  // Notice 2 is not needed because the QP solver assumes 1/2 factor in objective P term
  for (size_t i = 0; i < N; ++i) {
    const double ref_vel = v_ref_arr.at(i);
    // const double ref_vel = 1.0;
    P(IDX_B0 + i, IDX_B0 + i) += velocity_tracking_weight;
    q.at(IDX_B0 + i) += -velocity_tracking_weight * ref_vel * ref_vel;
  }

  // Slack variable costs
  for (size_t i = 0; i < N; ++i) {
    // Slack variable costs
    P(IDX_DELTA0 + i, IDX_DELTA0 + i) += over_v_weight;  // over velocity cost
    P(IDX_SIGMA0 + i, IDX_SIGMA0 + i) += over_a_weight;  // over acceleration cost
    P(IDX_GAMMA0 + i, IDX_GAMMA0 + i) += over_j_weight;  // over jerk cost
  }

  // Reference acceleration tracking: minimize weight * (a - a_ref)^2
  // Expands to: weight * a^2 - 2*weight*a_ref*a + const
  // P term: weight on a^2
  // q term: -2*weight*a_ref on a
  for (size_t i = 0; i < N; ++i) {
    const double a_ref = input.at(i).acceleration_mps2;
    P(IDX_A0 + i, IDX_A0 + i) += accel_tracking_weight;
    q.at(IDX_A0 + i) += -accel_tracking_weight * a_ref;
  }

  /**************************************************************/
  /**************** design constraint matrix ********************/
  /**************************************************************/

  size_t constr_idx = 0;

  // Soft Constraint Velocity Limit: 0 < b - delta < v_max^2
  // v_max is from max_velocity_per_point (includes lateral acceleration limits)
  for (size_t i = 0; i < N; ++i, ++constr_idx) {
    A(constr_idx, IDX_B0 + i) = 1.0;       // b_i
    A(constr_idx, IDX_DELTA0 + i) = -1.0;  // -delta_i
    upper_bound[constr_idx] = v_max_arr.at(i) * v_max_arr.at(i);
    lower_bound[constr_idx] = 0.0;
  }

  // Soft Constraint Acceleration Limit: a_min < a - sigma < a_max
  for (size_t i = 0; i < N; ++i, ++constr_idx) {
    A(constr_idx, IDX_A0 + i) = 1.0;       // a_i
    A(constr_idx, IDX_SIGMA0 + i) = -1.0;  // -sigma_i
    upper_bound[constr_idx] = a_max;
    lower_bound[constr_idx] = a_min;
  }

  // Soft Constraint Jerk Limit: jerk_min < pseudo_jerk[i] * ref_vel[i] - gamma[i] < jerk_max
  // -> jerk_min * ds < (a[i+1] - a[i]) * ref_vel[i] - gamma[i] * ds < jerk_max * ds
  for (size_t i = 0; i < N - 1; ++i, ++constr_idx) {
    const double ref_vel = std::max(0.5 * (v_ref_arr.at(i) + v_ref_arr.at(i + 1)), 0.1);
    const double ds = interval_dist_arr.at(i);
    A(constr_idx, IDX_A0 + i) = -ref_vel;     // -a[i] * ref_vel
    A(constr_idx, IDX_A0 + i + 1) = ref_vel;  //  a[i+1] * ref_vel
    A(constr_idx, IDX_GAMMA0 + i) = -ds;      // -gamma[i] * ds
    upper_bound[constr_idx] = j_max * ds;     //  jerk_max * ds
    lower_bound[constr_idx] = j_min * ds;     //  jerk_min * ds
  }

  // Dynamics constraint: b' = 2a ... (b(i+1) - b(i)) / ds = 2a(i)
  for (size_t i = 0; i < N - 1; ++i, ++constr_idx) {
    A(constr_idx, IDX_B0 + i) = -1.0;                            // b(i)
    A(constr_idx, IDX_B0 + i + 1) = 1.0;                         // b(i+1)
    A(constr_idx, IDX_A0 + i) = -2.0 * interval_dist_arr.at(i);  // a(i) * ds
    upper_bound[constr_idx] = 0.0;
    lower_bound[constr_idx] = 0.0;
  }

  // End Constraints for zero velocity
  if (zero_vel_id) {
    A(constr_idx, IDX_B0 + N - 1) = 1.0;
    upper_bound[constr_idx] = 0.0;
    lower_bound[constr_idx] = 0.0;
  }

  // Execute optimization
  const auto optval = qp_interface_->optimize(P, A, q, lower_bound, upper_bound);

  if (!qp_interface_->isSolved()) {
    RCLCPP_WARN(logger_, "Optimization failed: %s", qp_interface_->getStatus().c_str());
    return false;
  }

  const auto has_nan =
    std::any_of(optval.begin(), optval.end(), [](const auto v) { return std::isnan(v); });
  if (has_nan) {
    RCLCPP_WARN(logger_, "Optimization failed: result contains NaN values");
    return false;
  }

  // Extract velocity & acceleration from solution for optimized points
  for (size_t i = 0; i < N; ++i) {
    double b = optval.at(IDX_B0 + i);
    output.at(i).longitudinal_velocity_mps = std::sqrt(std::max(b, 0.0));
    output.at(i).acceleration_mps2 = optval.at(IDX_A0 + i);
  }

  // Set remaining points after stop point to zero velocity
  for (size_t i = N; i < total_size; ++i) {
    output.at(i).longitudinal_velocity_mps = 0.0;
    output.at(i).acceleration_mps2 = 0.0;
  }

  return true;
}

[[nodiscard]] std::optional<size_t> searchZeroVelocityIndex(
  const T & points_with_twist, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points_with_twist);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  constexpr double epsilon = 1e-3;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    if (std::fabs(points_with_twist.at(i).longitudinal_velocity_mps) < epsilon) {
      return i;
    }
  }

  return {};
}

std::vector<double> ContinuousJerkSmoother::calc_trajectory_interval_distance(
  const TrajectoryPoints & trajectory) const
{
  std::vector<double> intervals;
  intervals.reserve(trajectory.size() - 1);
  for (size_t i = 1; i < trajectory.size(); ++i) {
    const double dist =
      autoware_utils_geometry::calc_distance2d(trajectory.at(i).pose, trajectory.at(i - 1).pose);
    intervals.push_back(dist);
  }
  return intervals;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

std::vector<double> QPInterface::optimize(
  const Eigen::MatrixXd & P, const Eigen::MatrixXd & A, const std::vector<double> & q,
  const std::vector<double> & l, const std::vector<double> & u)
{
  initializeProblem(P, A, q, l, u);
  return optimizeImpl();
}

void QPInterface::initializeProblem(
  const Eigen::MatrixXd & P, const Eigen::MatrixXd & A, const std::vector<double> & q,
  const std::vector<double> & l, const std::vector<double> & u)
{
  // check if arguments are valid
  std::stringstream ss;
  if (P.rows() != P.cols()) {
    ss << "P.rows() and P.cols() are not the same. P.rows() = " << P.rows()
       << ", P.cols() = " << P.cols();
    throw std::invalid_argument(ss.str());
  }
  if (P.rows() != static_cast<int>(q.size())) {
    ss << "P.rows() and q.size() are not the same. P.rows() = " << P.rows()
       << ", q.size() = " << q.size();
    throw std::invalid_argument(ss.str());
  }
  if (P.rows() != A.cols()) {
    ss << "P.rows() and A.cols() are not the same. P.rows() = " << P.rows()
       << ", A.cols() = " << A.cols();
    throw std::invalid_argument(ss.str());
  }
  if (A.rows() != static_cast<int>(l.size())) {
    ss << "A.rows() and l.size() are not the same. A.rows() = " << A.rows()
       << ", l.size() = " << l.size();
    throw std::invalid_argument(ss.str());
  }
  if (A.rows() != static_cast<int>(u.size())) {
    ss << "A.rows() and u.size() are not the same. A.rows() = " << A.rows()
       << ", u.size() = " << u.size();
    throw std::invalid_argument(ss.str());
  }

  initializeProblemImpl(P, A, q, l, u);

  variables_num_ = q.size();
  constraints_num_ = l.size();
}

void OSQPInterface::initializeProblemImpl(
  const Eigen::MatrixXd & P, const Eigen::MatrixXd & A, const std::vector<double> & q,
  const std::vector<double> & l, const std::vector<double> & u)
{
  CSC_Matrix P_csc = calCSCMatrixTrapezoidal(P);
  CSC_Matrix A_csc = calCSCMatrix(A);
  initializeCSCProblemImpl(P_csc, A_csc, q, l, u);
}

CSC_Matrix calCSCMatrixTrapezoidal(const Eigen::MatrixXd & mat)
{
  const size_t elem = static_cast<size_t>(mat.nonZeros());
  const Eigen::Index rows = mat.rows();
  const Eigen::Index cols = mat.cols();

  if (rows != cols) {
    throw std::invalid_argument("Matrix must be square (n, n)");
  }

  std::vector<c_float> vals;
  vals.reserve(elem);
  std::vector<c_int> row_idxs;
  row_idxs.reserve(elem);
  std::vector<c_int> col_idxs;
  col_idxs.reserve(elem);

  // Construct CSC matrix arrays
  c_float val;
  Eigen::Index trap_last_idx = 0;
  c_int elem_count = 0;

  col_idxs.push_back(0);

  for (Eigen::Index j = 0; j < cols; j++) {              // col iteration
    for (Eigen::Index i = 0; i <= trap_last_idx; i++) {  // row iteration
      // Get values of nonzero elements
      val = mat(i, j);
      if (std::fabs(val) < 1e-9) {
        continue;
      }
      elem_count += 1;

      // Store values
      vals.push_back(val);
      row_idxs.push_back(i);
    }

    col_idxs.push_back(elem_count);
    trap_last_idx += 1;
  }

  CSC_Matrix csc_matrix = {vals, row_idxs, col_idxs};

  return csc_matrix;
}

CSC_Matrix calCSCMatrix(const Eigen::MatrixXd & mat)
{
  const size_t elem = static_cast<size_t>(mat.nonZeros());
  const Eigen::Index rows = mat.rows();
  const Eigen::Index cols = mat.cols();

  std::vector<c_float> vals;
  vals.reserve(elem);
  std::vector<c_int> row_idxs;
  row_idxs.reserve(elem);
  std::vector<c_int> col_idxs;
  col_idxs.reserve(elem);

  // Construct CSC matrix arrays
  c_float val;
  c_int elem_count = 0;

  col_idxs.push_back(0);

  for (Eigen::Index j = 0; j < cols; j++) {    // col iteration
    for (Eigen::Index i = 0; i < rows; i++) {  // row iteration
      // Get values of nonzero elements
      val = mat(i, j);
      if (std::fabs(val) < 1e-9) {
        continue;
      }
      elem_count += 1;

      // Store values
      vals.push_back(val);
      row_idxs.push_back(i);
    }

    col_idxs.push_back(elem_count);
  }

  CSC_Matrix csc_matrix = {vals, row_idxs, col_idxs};

  return csc_matrix;
}

void OSQPInterface::initializeCSCProblemImpl(
  CSC_Matrix P_csc, CSC_Matrix A_csc, const std::vector<double> & q, const std::vector<double> & l,
  const std::vector<double> & u)
{
  // Dynamic float arrays
  std::vector<double> q_tmp(q.begin(), q.end());
  std::vector<double> l_tmp(l.begin(), l.end());
  std::vector<double> u_tmp(u.begin(), u.end());
  double * q_dyn = q_tmp.data();
  double * l_dyn = l_tmp.data();
  double * u_dyn = u_tmp.data();

  /**********************
   * OBJECTIVE FUNCTION
   **********************/
  param_n_ = static_cast<int>(q.size());
  data_->m = static_cast<int>(l.size());

  /*****************
   * POPULATE DATA
   *****************/
  data_->n = param_n_;
  if (data_->P) free(data_->P);
  data_->P = csc_matrix(
    data_->n, data_->n, static_cast<c_int>(P_csc.vals_.size()), P_csc.vals_.data(),
    P_csc.row_idxs_.data(), P_csc.col_idxs_.data());
  data_->q = q_dyn;
  if (data_->A) free(data_->A);
  data_->A = csc_matrix(
    data_->m, data_->n, static_cast<c_int>(A_csc.vals_.size()), A_csc.vals_.data(),
    A_csc.row_idxs_.data(), A_csc.col_idxs_.data());
  data_->l = l_dyn;
  data_->u = u_dyn;

  // Setup workspace
  OSQPWorkspace * workspace;
  exitflag_ = osqp_setup(&workspace, data_.get(), settings_.get());
  work_.reset(workspace);
  work__initialized = true;
}

c_int osqp_setup(OSQPWorkspace** workp, const OSQPData* data, const OSQPSettings* settings);

# endif // #ifndef EMBEDDED

/**
 * Solve quadratic program
 *
 * The final solver information is stored in the \a work->info  structure

std::vector<double> OSQPInterface::optimizeImpl()
{
  osqp_solve(work_.get());

  double * sol_x = work_->solution->x;
  std::vector<double> sol_primal(sol_x, sol_x + param_n_);

  latest_work_info_ = *(work_->info);

  if (!enable_warm_start_) {
    work_.reset();
    work__initialized = false;
  }

  return sol_primal;
}

c_int osqp_solve(OSQPWorkspace *work);


# ifndef EMBEDDED

/**
 * Cleanup workspace by deallocating memory
 *

bool OSQPInterface::isSolved() const
{
  return latest_work_info_.status_val == 1;
}
